bool isValid(vector<vector<char>>& board, int row, int col, char digit) {
    for (int i = 0; i < 9; i++) {
        if (board[row][i] == digit) return false;       // row check
        if (board[i][col] == digit) return false;       // column check
        int boxRow = 3 * (row / 3) + i / 3;
        int boxCol = 3 * (col / 3) + i % 3;
        if (board[boxRow][boxCol] == digit) return false; // box check
    }
    return true;
}

bool solve(vector<vector<char>>& board) {
    for (int row = 0; row < 9; row++) {
        for (int col = 0; col < 9; col++) {
            if (board[row][col] != '.') continue; // already filled
            for (char digit = '1'; digit <= '9'; digit++) {
                if (!isValid(board, row, col, digit)) continue;
                board[row][col] = digit;            // choose
                if (solve(board)) return true;       // explore
                board[row][col] = '.';               // unchoose
            }
            return false; // no digit worked here, this whole branch fails
        }
    }
    return true; // reached the end of the grid with everything filled, solved
}
